package com.bank.treasury;

import java.util.logging.*;

public class TrapWaterDemo {
    private static final Logger log = Logger.getLogger(TrapWaterDemo.class.getName());
    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        TrappedLiquidityAnalyzer analyzer = new TrappedLiquidityAnalyzer();

        // Reserve skyline (in lakhs)
        int[] skyline = {0, 1, 0, 2, 1, 0, 1, 3, 2, 1, 2, 1};
        int trapped = analyzer.trap(skyline);
        log.info(() -> "Total trapped liquidity: " + trapped);
    }
}

