class TrappedLiquidityAnalyzer {
    private static final Logger log = Logger.getLogger(TrappedLiquidityAnalyzer.class.getName());

    // Two pointers with left/right running max. O(n) time, O(1) space.
    int trap(int[] h) {
        int left = 0, right = h.length - 1;
        int leftMax = 0, rightMax = 0, total = 0;
        while (left < right) {
            if (h[left] < h[right]) {       // left wall is the limiter
                if (h[left] >= leftMax) {
                    leftMax = h[left];      // new left wall, no water here
                } else {
                    total += leftMax - h[left]; // trapped above this bar
                }
                left++;
            } else {                         // right wall is the limiter
                if (h[right] >= rightMax) {
                    rightMax = h[right];
                } else {
                    total += rightMax - h[right];
                }
                right--;
            }
        }
        int ft = total;
        log.fine(() -> "Computed trapped = " + ft);
        return total;
    }
}

